DROP TABLE IF EXISTS `feedback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `feedback` (
  `id` varchar(30) NOT NULL,
  `attendee_id` varchar(30) NOT NULL,
  `q1_overall` int(11) DEFAULT '5',
  `q2_hydration` int(11) DEFAULT '5',
  `q3_stations` int(11) DEFAULT '5',
  `q4_valuable` text,
  `q5_suggestions` text,
  `rating` int(11) NOT NULL,
  `session_rating` int(11) NOT NULL,
  `recommend` varchar(10) NOT NULL,
  `comment` text,
  `submitted_at` varchar(30) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `attendee_id` (`attendee_id`),
  CONSTRAINT `feedback_ibfk_1` FOREIGN KEY (`attendee_id`) REFERENCES `attendees` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

